<?php
declare(strict_types=1);
require_once __DIR__.'/stats.php';
function memberReportAllowed(PDO $p,array $actor): bool {
 $q=$p->prepare("SELECT 1 FROM users WHERE id=? AND game_player_id=? AND is_chef=true AND status='active' AND script_enabled=true AND NOT must_change_password");$q->execute([$actor['id']??0,$actor['game_player_id']??0]);return (bool)$q->fetchColumn();
}
function memberReportDays(?string $first,?string $since,DateTimeImmutable $today): int {
 if(!$first)return 0;$date=(new DateTimeImmutable($first))->setTimezone(new DateTimeZone('Europe/Paris'))->setTime(0,0);
 if($since){$floor=(new DateTimeImmutable($since))->setTimezone(new DateTimeZone('Europe/Paris'))->setTime(0,0);if($floor>$date)$date=$floor;}
 return $date>$today?0:(int)$date->diff($today)->days+1;
}
function memberReport(PDO $p,PDO $game,array $actor,array $body): array {
 // No administrator/chain bypass. Re-read the exact chief right on every request.
 if(!memberReportAllowed($p,$actor))throw new DomainException('Le droit chef actif en base est nécessaire.',403);
 $q=$game->prepare("SELECT 1 FROM players WHERE server='s5' AND player_id=? AND upper(alliance_tag)='UPTEP' AND is_present=true");$q->execute([$actor['game_player_id']]);if(!$q->fetchColumn())throw new DomainException('Accès réservé aux chefs membres UPTEP.',403);
 $id=$body['player_id']??null;$pseudo=$body['q']??'';
 if($id!==null&&(!is_string($id)||!preg_match('/\A[1-9][0-9]{0,17}\z/',$id)))throw new DomainException('Joueur invalide.',422);
 if(!is_string($pseudo)||mb_strlen($pseudo)>100||($id===null&&trim($pseudo)===''))throw new DomainException('Joueur invalide.',422);
 $period=$body['period']??'30';if(!is_string($period)||!in_array($period,['7','30','90','all'],true))throw new DomainException('Période invalide.',422);
 $q=$game->prepare("SELECT player_id::text,pseudo,alliance_tag,on_holiday,is_banned FROM players WHERE server='s5' AND ".($id!==null?'player_id=?':'lower(pseudo)=lower(?)')." AND upper(alliance_tag)='UPTEP' AND is_present=true");$q->execute([$id??trim($pseudo)]);$target=$q->fetch(PDO::FETCH_ASSOC);if(!$target)throw new DomainException('Ce cadre est réservé aux membres actuels UPTEP.',404);$id=$target['player_id'];
 $today=new DateTimeImmutable('today',new DateTimeZone('Europe/Paris'));$until=$today->modify('+1 day')->format('c');$since=$period==='all'?null:$today->modify('-'.((int)$period-1).' days')->format('c');
 $q=$p->prepare("SELECT id::text,status,created_at,approved_at,last_login_at,last_site_seen_at,last_script_seen_at,script_enabled FROM users WHERE game_player_id=? ORDER BY id");$q->execute([$id]);$accounts=$q->fetchAll(PDO::FETCH_ASSOC);$account=count($accounts)===1?$accounts[0]:null;$stats=null;$evolution=[];$tokens=['count'=>0,'first_key_at'=>null,'last_key_at'=>null];
 if($account){
  $userId=$account['id'];unset($account['id']);
  $q=$p->prepare('SELECT count(*)::int AS count,min(created_at) AS first_key_at,max(created_at) AS last_key_at FROM script_tokens WHERE user_id=? AND player_id=?');$q->execute([$userId,$id]);$tokens=$q->fetch(PDO::FETCH_ASSOC);
  $q=$p->prepare('SELECT preferences FROM script_settings WHERE user_id=?');$q->execute([$userId]);$preferences=$q->fetchColumn();$account['collections']=$preferences===false?null:array_intersect_key(json_decode($preferences,true),array_flip(['buildings','research','army','economy']));
  $q=$p->prepare('SELECT data,updated_at,buildings_synced_at,research_synced_at,army_synced_at,resources_synced_at,workers_synced_at FROM user_stats WHERE user_id=?');$q->execute([$userId]);$stats=$q->fetch(PDO::FETCH_ASSOC)?:null;if($stats){$stored=json_decode($stats['data'],true,512,JSON_THROW_ON_ERROR);$stats['data']=[];foreach(STATS_GROUPS as $group=>[$title,$fields])if(isset($stored[$group])&&is_array($stored[$group]))$stats['data'][$group]=array_intersect_key($stored[$group],$fields);}
  $q=$p->prepare("WITH ranked AS (SELECT stat_group,data,observed_at,source,row_number() OVER(PARTITION BY stat_group ORDER BY observed_at,id) AS first_row,row_number() OVER(PARTITION BY stat_group ORDER BY observed_at DESC,id DESC) AS last_row,count(*) OVER(PARTITION BY stat_group) AS samples FROM member_stat_history WHERE user_id=? AND (?::timestamptz IS NULL OR observed_at>=?::timestamptz) AND observed_at<?::timestamptz) SELECT a.stat_group,a.data AS first_data,b.data AS last_data,a.observed_at AS first_at,b.observed_at AS last_at,b.source,a.samples FROM ranked a JOIN ranked b ON b.stat_group=a.stat_group AND b.last_row=1 WHERE a.first_row=1");$q->execute([$userId,$since,$since,$until]);
  foreach($q->fetchAll(PDO::FETCH_ASSOC) as $row){$group=$row['stat_group'];$first=json_decode($row['first_data'],true);$last=json_decode($row['last_data'],true);$delta=[];foreach(STATS_GROUPS[$group][1] as $key=>$label)if(isset($first[$key],$last[$key]))$delta[$key]=(string)((int)$last[$key]-(int)$first[$key]);$row['delta']=$delta;unset($row['first_data'],$row['last_data'],$row['stat_group']);
   if($group==='resources'&&(strtotime($row['last_at'])-strtotime($row['first_at']))>=3600){$hours=(string)(strtotime($row['last_at'])-strtotime($row['first_at']));$q2=$p->prepare('SELECT round(?::numeric*86400/?::numeric)::text AS food,round(?::numeric*86400/?::numeric)::text AS materials');$q2->execute([$delta['nourriture']??null,$hours,$delta['materiaux']??null,$hours]);$row['stock_change_per_day']=$q2->fetch(PDO::FETCH_ASSOC);}
   $evolution[$group]=$row;
  }
 }
 $q=$p->query("SELECT min(c.date_convoi) AS first_at FROM convois_effectues c JOIN demandes_convois d ON d.id=c.iddemande WHERE d.serveur='s5' AND NOT c.annule");$convoyFirst=$q->fetchColumn()?:null;$convoyDays=memberReportDays($convoyFirst,$since,$today);
 $floodFirst=$p->query('SELECT min(created_at) FROM floods')->fetchColumn()?:null;$floodDays=memberReportDays($floodFirst,$since,$today);
 $q=$p->prepare("SELECT CASE WHEN c.idenvoyeur=? THEN 'sent' ELSE 'received' END AS direction,count(*)::int AS count,COALESCE(sum(c.nbpomme),0)::text AS food,COALESCE(sum(c.nbmateriaux),0)::text AS materials,count(DISTINCT (c.date_convoi AT TIME ZONE 'Europe/Paris')::date)::int AS active_days,min(c.date_convoi) AS first_at,max(c.date_convoi) AS last_at,count(DISTINCT CASE WHEN c.idenvoyeur=? THEN d.iddemandeur ELSE c.idenvoyeur END)::int AS partners,count(*) FILTER(WHERE c.date_arrivee>now())::int AS travelling,count(*) FILTER(WHERE c.date_arrivee<=now())::int AS arrived FROM convois_effectues c JOIN demandes_convois d ON d.id=c.iddemande WHERE d.serveur='s5' AND NOT c.annule AND (c.idenvoyeur=? OR d.iddemandeur=?) AND (?::timestamptz IS NULL OR c.date_convoi>=?::timestamptz) AND c.date_convoi<?::timestamptz GROUP BY 1");$q->execute([$id,$id,$id,$id,$since,$since,$until]);$convoys=[];
 foreach($q->fetchAll(PDO::FETCH_ASSOC) as $row){$direction=$row['direction'];unset($row['direction']);$q2=$p->prepare('SELECT round(?::numeric/GREATEST(?::int,1))::text AS food,round(?::numeric/GREATEST(?::int,1))::text AS materials');$q2->execute([$row['food'],$convoyDays,$row['materials'],$convoyDays]);$row['daily']=$q2->fetch(PDO::FETCH_ASSOC);$convoys[$direction]=$row;}
 $q=$p->prepare("SELECT count(*) FILTER(WHERE c.idenvoyeur=?)::int AS canceled,round(100.0*COALESCE(sum(c.nbpomme+c.nbmateriaux::numeric) FILTER(WHERE c.idenvoyeur=? AND NOT c.annule),0)/NULLIF(sum(c.nbpomme+c.nbmateriaux::numeric) FILTER(WHERE NOT c.annule),0),1)::text AS alliance_share FROM convois_effectues c JOIN demandes_convois d ON d.id=c.iddemande WHERE d.serveur='s5' AND (?::timestamptz IS NULL OR c.date_convoi>=?::timestamptz) AND c.date_convoi<?::timestamptz");$q->execute([$id,$id,$since,$since,$until]);$convoyExtra=$q->fetch(PDO::FETCH_ASSOC);
 // Count canceled declarations for this sender only.
 $q=$p->prepare("SELECT count(*)::int FROM convois_effectues WHERE idenvoyeur=? AND annule AND (?::timestamptz IS NULL OR date_convoi>=?::timestamptz) AND date_convoi<?::timestamptz");$q->execute([$id,$since,$since,$until]);$convoyExtra['canceled']=(int)$q->fetchColumn();
 $q=$p->prepare("SELECT count(*)::int AS total,count(*) FILTER(WHERE annulee)::int AS canceled,count(*) FILTER(WHERE NOT annulee AND NOT valide AND NOT fini)::int AS pending,count(*) FILTER(WHERE NOT annulee AND valide AND NOT fini)::int AS ongoing,count(*) FILTER(WHERE NOT annulee AND fini AND NOT fin_manuelle)::int AS completed,count(*) FILTER(WHERE NOT annulee AND fin_manuelle)::int AS manual_completed,count(*) FILTER(WHERE NOT annulee AND auto_production)::int AS auto_production,COALESCE(sum(nbpomme_original) FILTER(WHERE NOT annulee),0)::text AS food,COALESCE(sum(nbmateriaux_original) FILTER(WHERE NOT annulee),0)::text AS materials FROM demandes_convois WHERE serveur='s5' AND iddemandeur=? AND (?::timestamptz IS NULL OR date_demande>=?::timestamptz) AND date_demande<?::timestamptz");$q->execute([$id,$since,$since,$until]);$requests=$q->fetch(PDO::FETCH_ASSOC);
 $q=$p->prepare("SELECT count(*)::int AS count,COALESCE(sum(nbpomme_restant),0)::text AS food,COALESCE(sum(nbmateriaux_restant),0)::text AS materials,min(date_demande) AS oldest_at FROM demandes_convois WHERE serveur='s5' AND iddemandeur=? AND NOT annulee AND NOT fini");$q->execute([$id]);$requests['outstanding']=$q->fetch(PDO::FETCH_ASSOC);
 $q=$p->prepare("SELECT count(*)::int AS count,COALESCE(sum(a.pommes_avant::numeric-a.pommes_apres),0)::text AS food,COALESCE(sum(a.materiaux_avant::numeric-a.materiaux_apres),0)::text AS materials FROM demandes_ajustements a JOIN demandes_convois d ON d.id=a.iddemande WHERE d.serveur='s5' AND d.iddemandeur=? AND NOT d.annulee AND (?::timestamptz IS NULL OR a.date_ajustement>=?::timestamptz) AND a.date_ajustement<?::timestamptz");$q->execute([$id,$since,$since,$until]);$requests['adjustments']=$q->fetch(PDO::FETCH_ASSOC);
 $q=$p->prepare("SELECT CASE WHEN sender_id=? THEN 'sent' ELSE 'received' END AS direction,count(*)::int AS count,count(DISTINCT (created_at AT TIME ZONE 'Europe/Paris')::date)::int AS active_days,count(DISTINCT CASE WHEN sender_id=? THEN target_pseudo ELSE sender_pseudo END)::int AS partners,min(created_at) AS first_at,max(created_at) AS last_at FROM floods WHERE (sender_id=? OR target_id=?) AND (?::timestamptz IS NULL OR created_at>=?::timestamptz) AND created_at<?::timestamptz GROUP BY 1");$q->execute([$id,$id,$id,$id,$since,$since,$until]);$floods=[];foreach($q->fetchAll(PDO::FETCH_ASSOC) as $row){$direction=$row['direction'];unset($row['direction']);$row['daily']=$floodDays?round((int)$row['count']/$floodDays,2):0;$floods[$direction]=$row;}
 $q=$p->prepare("SELECT id::text,objet,niveau,auto_production,nbpomme_original::text,nbmateriaux_original::text,nbpomme_restant::text,nbmateriaux_restant::text,date_demande,date_fin,valide,fini,fin_manuelle,annulee FROM demandes_convois WHERE serveur='s5' AND iddemandeur=? ORDER BY id DESC LIMIT 10");$q->execute([$id]);$requests['recent']=$q->fetchAll(PDO::FETCH_ASSOC);
 $q=$p->prepare("SELECT c.id::text,c.date_convoi,c.date_arrivee,c.nbpomme::text,c.nbmateriaux::text,c.pseudo_envoyeur,d.pseudo_demandeur,c.annule FROM convois_effectues c JOIN demandes_convois d ON d.id=c.iddemande WHERE d.serveur='s5' AND (c.idenvoyeur=? OR d.iddemandeur=?) AND (?::timestamptz IS NULL OR c.date_convoi>=?::timestamptz) AND c.date_convoi<?::timestamptz ORDER BY c.date_convoi DESC,c.id DESC LIMIT 10");$q->execute([$id,$id,$since,$since,$until]);$convoyExtra['recent']=$q->fetchAll(PDO::FETCH_ASSOC);
 $q=$p->prepare("SELECT sender_pseudo,target_pseudo,location,created_at,arrival_at FROM floods WHERE (sender_id=? OR target_id=?) AND (?::timestamptz IS NULL OR created_at>=?::timestamptz) AND created_at<?::timestamptz ORDER BY created_at DESC,id DESC LIMIT 10");$q->execute([$id,$id,$since,$since,$until]);$floodRecent=$q->fetchAll(PDO::FETCH_ASSOC);
 return ['target'=>$target,'generated_at'=>gmdate('c'),'period'=>['key'=>$period,'since'=>$since,'until'=>$until,'convoy_first_at'=>$convoyFirst,'convoy_days'=>$convoyDays,'flood_first_at'=>$floodFirst,'flood_days'=>$floodDays],'account'=>['registered'=>(bool)$accounts,'ambiguous'=>count($accounts)>1,'details'=>$account,'script'=>$tokens],'stats'=>$stats,'groups'=>STATS_GROUPS,'evolution'=>$evolution,'convoys'=>$convoys+$convoyExtra,'requests'=>$requests,'floods'=>$floods+['recent'=>$floodRecent]];
}
